def server(input: Inputs, output: Outputs, session: Session) -> None:
    from shiny import ui

    ui.input_slider("v0", "Velocidade Inicial (m/s):", min=10, max=80, value=35)
    ui.input_slider("angulo", "Ângulo de Decolagem (°):", min=15, max=85, value=45)
    ui.input_slider("massa", "Massa do Foguete (kg):", min=0.05, max=0.5, value=0.15, step=0.01)
    ui.input_slider("k", "Coeficiente de Arrasto (k):", min=0.000, max=0.005, value=0.002, step=0.0005)

    # ========================================================================

    import numpy as np
    import matplotlib.pyplot as plt
    from shiny import render

    @render.plot
    def grafico_trajetoria():
        # Obtém valores dos sliders
        v0 = input.v0()
        angulo = input.angulo()
        m = input.massa()
        k = input.k()
    
        # Física do Foguete
        dt = 0.005
        g = 9.81
        theta = np.radians(angulo)
        vx = v0 * np.cos(theta)
        vy = v0 * np.sin(theta)
    
        x, y = 0.0, 0.0
        x_list, y_list = [x], [y]
    
        while y >= 0:
            v = np.hypot(vx, vy)
            ax = -(k / m) * vx * v
            ay = -g - (k / m) * vy * v
        
            vx += ax * dt
            vy += ay * dt
            x += vx * dt
            y += vy * dt
        
            if y >= 0:
                x_list.append(x)
                y_list.append(y)

        # Gráfico Matplotlib
        fig, ax = plt.subplots(figsize=(8, 5))
        ax.plot(x_list, y_list, color='#2563eb', linewidth=2.5, label='Trajetória')
    
        # Ponto de Apogeu
        idx_max = np.argmax(y_list)
        ax.scatter(x_list[idx_max], y_list[idx_max], color='red', zorder=5, label=f'Apogeu ({y_list[idx_max]:.1f}m)')
    
        ax.set_title(f"Alcance Máximo: {x_list[-1]:.2f} metros", fontsize=12, fontweight='bold')
        ax.set_xlabel("Distância Horizontal (m)")
        ax.set_ylabel("Altura (m)")
        ax.grid(True, linestyle='--', alpha=0.6)
        ax.legend()
    
        return fig

    # ========================================================================



    return None


